            return AVERROR_INVALIDDATA;



        gce_flags = bytestream2_get_byteu(&s->gb);

        bytestream2_skipu(&s->gb, 2);    // delay during which the frame is shown

        gce_transparent_index = bytestream2_get_byteu(&s->gb);

