    mem = kvm_alloc_slot(s);

    mem->memory_size = size;

    mem->guest_phys_addr = start_addr;

    mem->userspace_addr = (unsigned long)(phys_ram_base + phys_offset);

    mem->flags = 0;



    kvm_vm_ioctl(s, KVM_SET_USER_MEMORY_REGION, mem);

