            contiguous_free_clusters++;

            if (first_gap) {

                /* If this is the first free cluster found, update

                 * *first_free_cluster accordingly */

                *first_free_cluster = cluster;

                first_gap = false;

            }

        } else if (contiguous_free_clusters) {

            contiguous_free_clusters = 0;

        }

    }



