            if (to) {

                inet->has_to = true;

                inet->to = to + offset;

            }

        }



        inet->ipv4 = ipv4;

        inet->has_ipv4 = has_ipv4;

        inet->ipv6 = ipv6;

        inet->has_ipv6 = has_ipv6;



        ret = baseport;

    }



    *retaddr = addr;



