                }

            }



            return 0;             /* Discard 0 sized packets */

        }



        if (trk->entry && pkt->stream_index < s->nb_streams)

            frag_duration = av_rescale_q(pkt->dts - trk->cluster[0].dts,

                                         s->streams[pkt->stream_index]->time_base,

