    int ret;

    int avail;



#if HAVE_PTHREADS

    if (s->fifo) {

        pthread_mutex_lock(&s->mutex);

        do {

            avail = av_fifo_size(s->fifo);

            if (avail) { // >=size) {

                uint8_t tmp[4];

                pthread_mutex_unlock(&s->mutex);



                av_fifo_generic_read(s->fifo, tmp, 4, NULL);

                avail= AV_RL32(tmp);

