    if (!(h->flags & AVIO_FLAG_NONBLOCK)) {

        ret = ff_network_wait_fd(s->udp_fd, 0);

        if (ret < 0)

            return ret;

    }

    ret = recv(s->udp_fd, buf, size, 0);



    return ret < 0 ? ff_neterrno() : ret;

}

