    if (result != 0) {

        av_log(NULL,AV_LOG_ERROR,"Frame decoding error!\n");

        return -1;

    }



    /* interleave */

    if (q->channels == 2) {

        q->fmt_conv.float_interleave(samples, (const float **)q->outSamples,

                                     1024, 2);

    }

    *data_size = 1024 * q->channels * av_get_bytes_per_sample(avctx->sample_fmt);



    return avctx->block_align;

}

