    memcpy(&req->crq, crq, sizeof(vscsi_crq));



    if (crq->s.format == VIOSRP_MAD_FORMAT) {

        done = vscsi_handle_mad_req(s, req);

    } else {

        done = vscsi_handle_srp_req(s, req);

    }



    if (done) {

