              " " TARGET_FMT_lx " %u\n", __func__, i, address, pid, tlb->EPN,

              mask, (uint32_t)tlb->PID);

    /* Check PID */

    if (tlb->PID != 0 && tlb->PID != pid)

        return -1;

    /* Check effective address */

    if ((address & mask) != tlb->EPN)

        return -1;

    *raddrp = (tlb->RPN & mask) | (address & ~mask);

